package io.vidocq.tools.dashboard.store;

import jakarta.data.repository.BasicRepository;
import jakarta.data.repository.Repository;
import jakarta.transaction.Transactional;

import java.time.Instant;
import java.util.Optional;

/** Generated by Mansart Data at compile time. */
@Transactional
@Repository
public interface QueueSampleRepository extends BasicRepository<QueueSample, Long> {

    /** The sample of a minute, to raise its maxima: one row per org and minute. */
    Optional<QueueSample> findByOrgAndMinute(String org, Instant minute);
}
